class Solution {
    int answer = 0;

    int dfs(Node* node) {
        if (!node) {
            return 0;
        }
        int first = 0;
        int second = 0;
        for (Node* child : node->children) {
            int height = dfs(child) + 1;
            if (height > first) {
                second = first;
                first = height;
            } else if (height > second) {
                second = height;
            }
        }
        answer = max(answer, first + second);
        return first;
    }

public:
    int diameter(Node* root) {
        answer = 0;
        dfs(root);
        return answer;
    }
};
